INSERT INTO `front_details` (`id`, `language_setting_id`, `header_title`, `header_description`, `image`, `feature_with_image_heading`, `review_heading`, `feature_with_icon_heading`, `comments_heading`, `price_heading`, `price_description`, `faq_heading`, `faq_description`, `contact_heading`, `footer_copyright_text`, `created_at`, `updated_at`) VALUES
(1, 1, 'All-in-One POS For Every Business', 'Manage your entire business from one platform. Track sales, inventory, and customers effortlessly. Save time, reduce errors and focus on what truly matters- Growth', NULL, 'Take Control Of Your Business', 'Real Stories, Real Impact.', 'Powerful Features Built To Elevate Your Business Operations', NULL, 'Simple & Transparent Pricing', 'Get everything you need to manage your business with one affordable plan.', 'Your questions, answered', 'Answers to the most frequently asked questions.', 'Contact Us Today', '© 2025 TableTrack. All Rights Reserved.', '2025-07-16 22:42:50', '2025-10-20 01:59:01');
INSERT INTO `front_faq_settings` (`id`, `language_setting_id`, `question`, `answer`, `created_at`, `updated_at`) VALUES
(1, 1, 'What is Snappi and how can it help my business?', '<div><strong>Snappi</strong> is a powerful business management software designed to simplify your daily operations. From tracking orders and managing inventory to updating brands and handling staff roles &amp; more, Snappi keeps everything running smoothly.</div>', NULL, '2025-10-09 17:14:27'),
(2, 1, 'What subscription plans does Snappi offer?', '<div>We offer two flexible subscription packages to suit your business needs:</div><ul><li><strong>Snappi Standard</strong> – Perfect for small or growing business</li><li><strong>Snappi Premium</strong> – Designed for larger operations with advanced features<br> <em>Not sure where to begin?</em> Try our 14<strong>-days Free Trial</strong>—no payment required!</li></ul>', NULL, '2025-10-20 01:26:49'),
(3, 1, 'How do I sign up for the 14-days free trial?', '<div>&nbsp;Getting started is easy! Just visit <a href=\"https://www.food.ogamanaja.com.ng\">www.s</a>nappi.com.ng and click <strong>“Start Free Trial.”</strong> You\'ll get full access to explore all core features without any upfront cost. No card needed until you’re ready to upgrade.&nbsp;</div>', NULL, '2025-10-20 01:27:44'),
(4, 1, 'How can I pay for my Snappi subscription?', '<div>We accept secure online payments via <strong>Paystack</strong>, giving you flexible options with debit cards, bank transfers, and more. You’ll receive an email reminder before your trial ends so you can upgrade without interruptions.</div>', NULL, '2025-10-09 17:16:17'),
(5, 1, 'Can I customize access for different staff roles?', '<div>&nbsp;Yes! Snappi allows you to create <strong>separate logins</strong> for each staff member, with <strong>role-based permissions</strong>. Whether it\'s sale staff, or managers—everyone gets access to only what they need.&nbsp;</div>', NULL, '2025-10-09 17:16:44'),
(6, 1, 'How can I get support if I need help?', '<div>&nbsp;We’re here to help! Reach out to us anytime via:<br>&nbsp;📧 <strong>Email:</strong> support@snappi.com.ng<br> 📞 <strong>Phone/WhatsApp:</strong> +234 7064573705<br> Or visit <a href=\"https://www.food.ogamanaja.com.ng\">www.snappi.com.ng</a> to access the contact menu—we’ll respond promptly.&nbsp;</div>', NULL, '2025-10-20 01:30:28');
INSERT INTO `front_features` (`id`, `language_setting_id`, `title`, `description`, `image`, `icon`, `type`, `created_at`, `updated_at`) VALUES
(1, 1, 'Easily Manage All Your Sales', 'No more mix-ups or missed transactions. From in-store purchases to online orders, everything stays organized in one place — boosting efficiency and keeping you on track.', 'c685e548de62e1f40625f02939747943.jpeg', NULL, 'image', NULL, '2025-10-20 00:32:40'),
(2, 1, 'Smarter Scheduling, Better Service', 'Keep your customers satisfied and operations smooth. With real-time tracking and easy management, you’ll save time and make the most of every opportunity—even during your busiest hours', 'f4a2f49adf4c583296f2459247a7a26c.jpeg', NULL, 'image', NULL, '2025-10-20 00:48:11'),
(3, 1, 'Instant Product Management at Your Fingertips', 'Update your items anytime—add new products, adjust prices, and highlight promotions instantly. Keep everything in sync so you and your customers always see the latest.', 'b4296641debf223dff87a7d1fa0d573c.png', NULL, 'image', NULL, '2025-10-20 00:57:19'),
(4, 1, 'QR Code Shopping', 'Tap. Order. Enjoy. Contact-Free.', '<svg width=\"30\" height=\"30\" class=\"svg icon bi bi-qr-code-scan text-skin-base dark:text-skin-base size-6\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" data-slot=\"icon\">\n  <path d=\"M4.75 4.25a.5.5 0 1 0 0 1 .5.5 0 0 0 0-1Z\"/>\n  <path fill-rule=\"evenodd\" d=\"M2 3.5A1.5 1.5 0 0 1 3.5 2H6a1.5 1.5 0 0 1 1.5 1.5V6A1.5 1.5 0 0 1 6 7.5H3.5A1.5 1.5 0 0 1 2 6V3.5Zm1.5 0H6V6H3.5V3.5Z\" clip-rule=\"evenodd\"/>\n  <path d=\"M4.25 11.25a.5.5 0 1 1 1 0 .5.5 0 0 1-1 0Z\"/>\n  <path fill-rule=\"evenodd\" d=\"M2 10a1.5 1.5 0 0 1 1.5-1.5H6A1.5 1.5 0 0 1 7.5 10v2.5A1.5 1.5 0 0 1 6 14H3.5A1.5 1.5 0 0 1 2 12.5V10Zm1.5 2.5V10H6v2.5H3.5Z\" clip-rule=\"evenodd\"/>\n  <path d=\"M11.25 4.25a.5.5 0 1 0 0 1 .5.5 0 0 0 0-1Z\"/>\n  <path fill-rule=\"evenodd\" d=\"M10 2a1.5 1.5 0 0 0-1.5 1.5V6A1.5 1.5 0 0 0 10 7.5h2.5A1.5 1.5 0 0 0 14 6V3.5A1.5 1.5 0 0 0 12.5 2H10Zm2.5 1.5H10V6h2.5V3.5Z\" clip-rule=\"evenodd\"/>\n  <path d=\"M8.5 9.417a.917.917 0 1 1 1.833 0 .917.917 0 0 1-1.833 0ZM8.5 13.083a.917.917 0 1 1 1.833 0 .917.917 0 0 1-1.833 0ZM13.083 8.5a.917.917 0 1 0 0 1.833.917.917 0 0 0 0-1.833ZM12.166 13.084a.917.917 0 1 1 1.833 0 .917.917 0 0 1-1.833 0ZM11.25 10.333a.917.917 0 1 0 0 1.833.917.917 0 0 0 0-1.833Z\"/>\n</svg>\n', 'qr-code', 'icon', NULL, '2025-10-09 17:12:54'),
(5, 1, 'Payment Gateway Integration', 'Easy, Safe, and Flexible Payments via Paystack', '<svg width=\"30\" height=\"30\" class=\"svg icon bi bi-qr-code-scan text-skin-base dark:text-skin-base size-6\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" data-slot=\"icon\">\n  <path d=\"M2.5 3A1.5 1.5 0 0 0 1 4.5V5h14v-.5A1.5 1.5 0 0 0 13.5 3h-11Z\"/>\n  <path fill-rule=\"evenodd\" d=\"M15 7H1v4.5A1.5 1.5 0 0 0 2.5 13h11a1.5 1.5 0 0 0 1.5-1.5V7ZM3 10.25a.75.75 0 0 1 .75-.75h.5a.75.75 0 0 1 0 1.5h-.5a.75.75 0 0 1-.75-.75Zm3.75-.75a.75.75 0 0 0 0 1.5h2.5a.75.75 0 0 0 0-1.5h-2.5Z\" clip-rule=\"evenodd\"/>\n</svg>\n', 'credit-card', 'icon', NULL, '2025-07-18 22:29:10'),
(6, 1, 'Staff Management', 'Each Staff Member Gets Their Own Login and the Right Access', '<svg width=\"30\" height=\"30\" class=\"svg icon bi bi-qr-code-scan text-skin-base dark:text-skin-base size-6\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" data-slot=\"icon\">\n  <path d=\"M8 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM12.735 14c.618 0 1.093-.561.872-1.139a6.002 6.002 0 0 0-11.215 0c-.22.578.254 1.139.872 1.139h9.47Z\"/>\n</svg>\n', 'user', 'icon', NULL, '2025-07-18 22:30:59'),
(7, 1, 'POS (Point of Sale)', 'All-in-One POS Integration for Seamless Operations', '<svg width=\"30\" height=\"30\" class=\"svg icon bi bi-qr-code-scan text-skin-base dark:text-skin-base size-6\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" data-slot=\"icon\">\n  <path fill-rule=\"evenodd\" d=\"M2 4.25A2.25 2.25 0 0 1 4.25 2h7.5A2.25 2.25 0 0 1 14 4.25v5.5A2.25 2.25 0 0 1 11.75 12h-1.312c.1.128.21.248.328.36a.75.75 0 0 1 .234.545v.345a.75.75 0 0 1-.75.75h-4.5a.75.75 0 0 1-.75-.75v-.345a.75.75 0 0 1 .234-.545c.118-.111.228-.232.328-.36H4.25A2.25 2.25 0 0 1 2 9.75v-5.5Zm2.25-.75a.75.75 0 0 0-.75.75v4.5c0 .414.336.75.75.75h7.5a.75.75 0 0 0 .75-.75v-4.5a.75.75 0 0 0-.75-.75h-7.5Z\" clip-rule=\"evenodd\"/>\n</svg>\n', 'computer-desktop', 'icon', NULL, '2025-07-18 22:32:30'),
(8, 1, 'Flexible Layouts', 'Set up your space exactly how your business works best', '<svg width=\"30\" height=\"30\" class=\"svg icon bi bi-qr-code-scan text-skin-base dark:text-skin-base size-6\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" data-slot=\"icon\">\n  <path fill-rule=\"evenodd\" d=\"M15 11a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v6ZM7.25 7.5a.5.5 0 0 0-.5-.5H3a.5.5 0 0 0-.5.5V8a.5.5 0 0 0 .5.5h3.75a.5.5 0 0 0 .5-.5v-.5Zm1.5 3a.5.5 0 0 1 .5-.5H13a.5.5 0 0 1 .5.5v.5a.5.5 0 0 1-.5.5H9.25a.5.5 0 0 1-.5-.5v-.5ZM13.5 8v-.5A.5.5 0 0 0 13 7H9.25a.5.5 0 0 0-.5.5V8a.5.5 0 0 0 .5.5H13a.5.5 0 0 0 .5-.5Zm-6.75 3.5a.5.5 0 0 0 .5-.5v-.5a.5.5 0 0 0-.5-.5H3a.5.5 0 0 0-.5.5v.5a.5.5 0 0 0 .5.5h3.75Z\" clip-rule=\"evenodd\"/>\n</svg>\n', 'table-cells', 'icon', NULL, '2025-10-20 01:02:43'),
(9, 1, '⁠Smart Order Management', 'Stay organized and keep every order on track', '<svg width=\"30\" height=\"30\" class=\"svg icon bi bi-qr-code-scan text-skin-base dark:text-skin-base size-6\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" data-slot=\"icon\">\n  <path fill-rule=\"evenodd\" d=\"M15 8c0 .982-.472 1.854-1.202 2.402a2.995 2.995 0 0 1-.848 2.547 2.995 2.995 0 0 1-2.548.849A2.996 2.996 0 0 1 8 15a2.996 2.996 0 0 1-2.402-1.202 2.995 2.995 0 0 1-2.547-.848 2.995 2.995 0 0 1-.849-2.548A2.996 2.996 0 0 1 1 8c0-.982.472-1.854 1.202-2.402a2.995 2.995 0 0 1 .848-2.547 2.995 2.995 0 0 1 2.548-.849A2.995 2.995 0 0 1 8 1c.982 0 1.854.472 2.402 1.202a2.995 2.995 0 0 1 2.547.848c.695.695.978 1.645.849 2.548A2.996 2.996 0 0 1 15 8Zm-3.291-2.843a.75.75 0 0 1 .135 1.052l-4.25 5.5a.75.75 0 0 1-1.151.043l-2.25-2.5a.75.75 0 1 1 1.114-1.004l1.65 1.832 3.7-4.789a.75.75 0 0 1 1.052-.134Z\" clip-rule=\"evenodd\"/>\n</svg>\n', 'check-badge', 'icon', NULL, '2025-10-20 01:04:04'),
(10, 1, 'Bill Printing', 'Bill Customers Quickly and Correctly, Every Time', '<svg width=\"30\" height=\"30\" class=\"svg icon bi bi-qr-code-scan text-skin-base dark:text-skin-base size-6\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" data-slot=\"icon\">\n  <path fill-rule=\"evenodd\" d=\"M13.836 2.477a.75.75 0 0 1 .75.75v3.182a.75.75 0 0 1-.75.75h-3.182a.75.75 0 0 1 0-1.5h1.37l-.84-.841a4.5 4.5 0 0 0-7.08.932.75.75 0 0 1-1.3-.75 6 6 0 0 1 9.44-1.242l.842.84V3.227a.75.75 0 0 1 .75-.75Zm-.911 7.5A.75.75 0 0 1 13.199 11a6 6 0 0 1-9.44 1.241l-.84-.84v1.371a.75.75 0 0 1-1.5 0V9.591a.75.75 0 0 1 .75-.75H5.35a.75.75 0 0 1 0 1.5H3.98l.841.841a4.5 4.5 0 0 0 7.08-.932.75.75 0 0 1 1.025-.273Z\" clip-rule=\"evenodd\"/>\n</svg>\n', 'arrow-path', 'icon', NULL, '2025-07-18 22:40:11'),
(11, 1, 'Reports', 'Insightful Reports for Smarter Decision-Making', '<svg width=\"30\" height=\"30\" class=\"svg icon bi bi-qr-code-scan text-skin-base dark:text-skin-base size-6\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" data-slot=\"icon\">\n  <path fill-rule=\"evenodd\" d=\"M9.808 4.057a.75.75 0 0 1 .92-.527l3.116.849a.75.75 0 0 1 .528.915l-.823 3.121a.75.75 0 0 1-1.45-.382l.337-1.281a23.484 23.484 0 0 0-3.609 3.056.75.75 0 0 1-1.07.01L6 8.06l-3.72 3.72a.75.75 0 1 1-1.06-1.061l4.25-4.25a.75.75 0 0 1 1.06 0l1.756 1.755a25.015 25.015 0 0 1 3.508-2.85l-1.46-.398a.75.75 0 0 1-.526-.92Z\" clip-rule=\"evenodd\"/>\n</svg>\n', 'arrow-trending-up', 'icon', NULL, '2025-07-18 22:41:31');
INSERT INTO `front_review_settings` (`id`, `language_setting_id`, `reviews`, `reviewer_name`, `reviewer_designation`, `created_at`, `updated_at`) VALUES
(1, 1, 'This platform has completely transformed how we run our fabric store. Managing sales, inventory, and customer orders all in one place has made things so much easier. It’s saved us time, reduced errors, and improved how we serve our customers both in-store and online. Truly a game changer for our business.', 'Peace Obinnakwelu', 'Owner of Dressup Fabrics', NULL, '2025-10-20 01:59:40'),
(2, 1, 'The QR code menu and seamless payment system have been amazing from day one. Our customers love the convenience of ordering and paying with ease, and it’s helped us serve more people faster and more efficiently.', 'Herbert Ibifaa', 'Owner of Lion\'s Gaspet', NULL, '2025-10-20 01:24:28'),
(3, 1, 'Managing a pharmacy used to be stressful, but this system really changed that. I can now monitor stock levels, handle sales, and update product information without the usual chaos. Everything runs smoother, and my team works more efficiently than ever.', 'Mathais Eleluwor', 'Manager of Beta Pharmacy & Stores', NULL, '2025-10-20 01:23:24');
